diff --git a/src/io/sales-import.js b/src/io/sales-import.js
new file mode 100644
index 0000000..65615de
--- /dev/null
+++ b/src/io/sales-import.js
@@ -0,0 +1,58 @@
+import { memoryStore } from "../db/store.js";
+import { AppError } from "../errors.js";
+import { t } from "../i18n/messages.js";
+import { config } from "../config.js";
+import { getDish } from "../domain/menu.js";
+import { getRecipe, scaled } from "../domain/recipes.js";
+import { consume } from "../domain/batches.js";
+import { isDate } from "../dates.js";
+import { parseCsv } from "./csv.js";
+
+const HEADER = ["ticket", "soldAt", "dishId", "qty"];
+const CSV_LINE = /^(?:[^",]*|"(?:[^"]|"")*")(?:,(?:[^",]*|"(?:[^"]|"")*"))*$/;
+
+/** Imports a complete sales file atomically, skipping previously imported tickets. */
+export function importSales(store, text) {
+  const lines = text.split(/\r?\n/);
+  const header = lines.shift() ?? "";
+  if (!CSV_LINE.test(header) || JSON.stringify(parseCsv(header)[0]?.map((x) => x.trim())) !== JSON.stringify(HEADER))
+    throw new AppError("bad_request", { reason: "row 1: expected ticket,soldAt,dishId,qty" });
+  const copy = memoryStore(store.data);
+  const existing = new Set(copy.data.sales.map((s) => s.ticket));
+  const imported = new Set();
+  let dishes = 0;
+  for (let i = 0; i < lines.length; i++) {
+    const line = lines[i];
+    if (!line.trim()) continue;
+    const row = i + 2;
+    try {
+      if (!CSV_LINE.test(line)) throw new AppError("bad_request", { reason: "invalid CSV" });
+      const fields = parseCsv(line)[0].map((x) => x.trim());
+      if (fields.length !== 4) throw new AppError("bad_request", { reason: "expected four columns" });
+      const [ticket, soldAt, dishText, qtyText] = fields;
+      if (!ticket) throw new AppError("bad_request", { reason: "ticket is required" });
+      const instant = /^(\d{4}-\d{2}-\d{2})T(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d+)?(?:Z|[+-](?:[01]\d|2[0-3]):[0-5]\d)$/;
+      const match = instant.exec(soldAt);
+      if (!match || !Number.isFinite(Date.parse(soldAt)) || !isDate(match[1])) throw new AppError("bad_request", { reason: "invalid soldAt" });
+      if (!/^[1-9]\d*$/.test(dishText) || !Number.isSafeInteger(Number(dishText))) throw new AppError("bad_request", { reason: "invalid dishId" });
+      if (!/^[1-9]\d*$/.test(qtyText) || !Number.isSafeInteger(Number(qtyText))) throw new AppError("bad_request", { reason: "invalid qty" });
+      const dish = getDish(copy, Number(dishText));
+      const recipe = getRecipe(copy, dish.recipeId);
+      if (existing.has(ticket)) continue;
+      const qty = Number(qtyText);
+      const at = new Date(soldAt).toISOString();
+      const ingredients = scaled(recipe, qty);
+      for (const ingredient of ingredients) {
+        if (ingredient.qty > 0) consume(copy, ingredient.itemId, ingredient.qty, { at, ref: `sale:${ticket}` });
+      }
+      copy.data.sales.push({ ticket, soldAt: at, dishId: dish.id, qty, ingredients });
+      imported.add(ticket);
+      dishes += qty;
+    } catch (error) {
+      if (!(error instanceof AppError)) throw error;
+      throw new AppError("bad_request", { reason: `row ${row}: ${t(error.code, config.defaultLanguage, error.params)}` });
+    }
+  }
+  store.data = copy.data;
+  return { tickets: imported.size, dishes };
+}
